import{_ as e,c as r,o as p,ae as l}from"./chunks/framework.C-JRAr_X.js";const n="/NEWTEST/assets/4-3._%EC%9C%A1%EC%95%84%EC%8B%9C%EA%B0%84_%EC%82%AC%EC%9A%A9%EC%A7%80%EC%B9%A8-image1.CajT02w1.jpeg",d="/NEWTEST/assets/4-3._%EC%9C%A1%EC%95%84%EC%8B%9C%EA%B0%84_%EC%82%AC%EC%9A%A9%EC%A7%80%EC%B9%A8-image2.CLkUrhAn.jpeg",s="/NEWTEST/assets/4-3._%EC%9C%A1%EC%95%84%EC%8B%9C%EA%B0%84_%EC%82%AC%EC%9A%A9%EC%A7%80%EC%B9%A8-image3.J3eWvSe1.jpeg",o="/NEWTEST/assets/4-3._%EC%9C%A1%EC%95%84%EC%8B%9C%EA%B0%84_%EC%82%AC%EC%9A%A9%EC%A7%80%EC%B9%A8-image4.ehvmb7GC.jpeg",a="/NEWTEST/assets/4-4._%EC%9E%A5%EA%B8%B0%EC%9E%AC%EC%A7%81%EC%9E%90_%EC%9E%AC%EC%B6%A9%EC%A0%84%ED%9C%B4%EA%B0%80_%EC%82%AC%EC%9A%A9%EC%A7%80%EC%B9%A8-image5.C41bIdY3.jpeg",E=JSON.parse('{"title":"4-4. 장기재직자 재충전휴가 사용지침","description":"","frontmatter":{"title":"4-4. 장기재직자 재충전휴가 사용지침"},"headers":[],"relativePath":"manual/4-4._장기재직자_재충전휴가_사용지침.md","filePath":"manual/4-4._장기재직자_재충전휴가_사용지침.md"}'),g={name:"manual/4-4._장기재직자_재충전휴가_사용지침.md"};function h(i,t,c,y,b,x){return p(),r("div",null,t[0]||(t[0]=[l('<p>“문화와 예술로 행복한 서울 만들기”</p><table tabindex="0"><thead><tr><th style="text-align:center;">문서번호</th><th>인사팀-715</th></tr></thead><tbody><tr><td style="text-align:center;">보존기간</td><td>준영구</td></tr><tr><td style="text-align:center;">결재일자</td><td>2024. 03. 04.</td></tr><tr><td style="text-align:center;">공개여부</td><td>공개</td></tr><tr><td style="text-align:center;">방침번호</td><td>대표이사 방침 제(112)호</td></tr></tbody></table><table><colgroup><col style="width:26%;"><col style="width:23%;"><col style="width:24%;"><col style="width:25%;"></colgroup><thead><tr><th style="text-align:center;"><p>★사원</p></th><th><p>팀장</p></th><th><p>본부장</p></th><th style="text-align:center;"><p>대표이사</p></th></tr></thead><tbody><tr><td><p><img src="'+n+'" style="width:0.42205in;height:0.125in;"></p></td><td><p><img src="'+d+'" style="width:0.40959in;height:0.11667in;"></p></td><td><p><img src="'+s+'" style="width:0.42297in;height:0.125in;"></p></td><td style="text-align:center;"><p><strong>03/04</strong></p><p><img src="'+o+'" style="width:0.40655in;height:0.125in;"></p></td></tr><tr><td style="text-align:center;"><p>협 조</p></td><td colspan="3"></td></tr><tr><td colspan="4"></td></tr></tbody></table><p><strong>서울문화재단 장기재직자 재충전휴가 사용지침 개정</strong></p><p><img src="'+a+'" style="width:3.45717in;height:0.70469in;"></p><p><strong>서울문화재단 장기재직자 재충전휴가 사용지침 개정</strong></p><p><strong>「서울문화재단 복무규정」및「서울특별시 공무원 휴가 등 업무지침(2024.2.7.)에 근거하여 서울문화재단 장기재직자 재충전휴가 사용과 관련한 세부 운영지침을 마련 하여 운영하고자 함</strong></p><h1 id="추진근거" tabindex="-1">추진근거 <a class="header-anchor" href="#추진근거" aria-label="Permalink to &quot;추진근거&quot;">​</a></h1><p><strong>□</strong> 서울문화재단 복무규정 제30조의2(특별휴가) 제1항</p><p>Ⅰ</p><p><strong>제30조의2(특별휴가)</strong> ① 대표이사는 재직기간이 5년 이상 10년 미만인 직원에게 해당 재직 기간 중 5일, 10년 이상 20년 미만인 직원에게 해당 재직기간 중 15일, 20년 이상 30년</p><p>미만 및 30년 이상 재직한 직원에게는 해당 재직기간 중 각각 25일의 휴가를 허가할 수 있으며, 운영에 필요한 사항은 대표이사가 따로 정한다. &lt;개정 2023. 09. 26.&gt;</p><ul><li>서울특별시 공무원 휴가 등 업무지침(2024.2.7.)</li></ul><p>장기재직휴가는 주기 내 분할하여 실시할 수 있으며, 업무, 개인의 사정에 따라 25일인 경우 5회로, 15일의 경우 3회로 나누어 주기 내 사용이 가능하며, 필요 시 주기에 부여된 휴가를 같은 해에 모두 사용할 수 있음</p><p><strong>□</strong> 대표이사 방침 제309(인사팀-2975, 2023.10.19.)호 “서울문화재단 장기재직자 재충전휴가 사용지침 개정”</p><h1 id="주요-개선사항" tabindex="-1">주요 개선사항 <a class="header-anchor" href="#주요-개선사항" aria-label="Permalink to &quot;주요 개선사항&quot;">​</a></h1><p><strong>개선 후</strong></p><p><strong>▶</strong></p><p>Ⅱ</p><table><colgroup><col style="width:44%;"><col style="width:22%;"><col style="width:32%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>구 분</strong></p></th><th style="text-align:center;"><p><strong>휴가 일수</strong></p></th><th><p><strong>비 고</strong></p></th></tr></thead><tbody><tr><td style="text-align:center;"><p>30년 이상</p></td><td style="text-align:center;"><p>25</p></td><td rowspan="4"><p>분할사용 불가</p></td></tr><tr><td style="text-align:center;"><p>20년 이상</p><p>30년 미만</p></td><td style="text-align:center;"><p>25</p></td></tr><tr><td style="text-align:center;"><p>10년 이상</p><p>20년 미만</p></td><td style="text-align:center;"><p>15</p></td></tr><tr><td style="text-align:center;"><p>5년 이상</p><p>10년 미만</p></td><td style="text-align:center;"><p>5</p></td></tr></tbody></table><table tabindex="0"><thead><tr><th><strong>구 분</strong></th><th><strong>기존</strong></th></tr></thead><tbody><tr><td><strong>휴가 분할사용 허가</strong></td><td></td></tr></tbody></table><table><colgroup><col style="width:40%;"><col style="width:19%;"><col style="width:17%;"><col style="width:22%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>구 분</strong></p></th><th style="text-align:center;"><p><strong>휴가 일수</strong></p></th><th style="text-align:center;"><p><strong>최대</strong></p><p><strong>사용</strong></p><p><strong>횟수</strong></p></th><th><p><strong>비 고</strong></p></th></tr></thead><tbody><tr><td style="text-align:center;"><p>30년 이상</p></td><td style="text-align:center;"><p>25</p></td><td style="text-align:center;"><p>5</p></td><td></td></tr><tr><td style="text-align:center;"><p>20년 이상</p><p>30년 미만</p></td><td style="text-align:center;"><p>25</p></td><td style="text-align:center;"><p>5</p></td><td></td></tr><tr><td style="text-align:center;"><p>10년 이상</p><p>20년 미만</p></td><td style="text-align:center;"><p>15</p></td><td style="text-align:center;"><p>3</p></td><td></td></tr><tr><td style="text-align:center;"><p>5년 이상</p><p>10년 미만</p></td><td style="text-align:center;"><p>5</p></td><td style="text-align:center;"><p>1</p></td><td style="text-align:center;"><p>분할사용</p><p>불가</p></td></tr></tbody></table><table><colgroup><col style="width:10%;"><col style="width:8%;"><col style="width:37%;"><col style="width:44%;"></colgroup><thead><tr><th colspan="2" style="text-align:center;"><p><strong>연도 중 기간도래자의 사용 기한 연장</strong></p></th><th style="text-align:center;"><p>입사일로부터 재직기간 산정하여 해당 구분연수 중 사용 원칙 (미사용 시 소멸)</p></th><th rowspan="4"><p>연도 중 기간 도래자의 경우,</p><p><strong>▶</strong> 해당연도 말일까지 사용 기한 연장</p><p>(미사용 시 소멸)</p><p>▼</p><p><strong>▶</strong> ‘장기재직자 휴가 재충전휴가 시작일로부터</p><p>계획’ 기안 3일 전</p><p>▼ 근무상황부</p><p>시행 시점 전</p><p>상신</p><p><strong>1) 팀장, 매니저 및 팀원</strong> 기안자&gt;부서장(검토)&gt;복무담당(협조)</p><p>&gt;실장(검토)&gt;본부장(전결)</p><p>※ 본부장 없는 부서는 실장(전결)</p><p><strong>▶ 2) 실장</strong></p><p>기안자&gt;본부장(검토)&gt;복무담당(협조)</p><p>&gt;대표이사(결재)</p><p><strong>3) 본부장 및 전문위원</strong> 기안자&gt;복무담당(협조)&gt;대표이사(결재)</p><p><strong>▶</strong></p></th></tr><tr><th rowspan="2"><p><strong>사용절차 간소화</strong></p></th><th><p><strong>신청 기한 완화</strong></p></th><th><p>▼</p><p>‘장기재직자 휴가 재충전휴가 시작일로부터 계획’ 기안 일주일 전</p><p>▼ 근무상황부</p><p>시행 시점 전</p><p>상신</p></th></tr><tr><th><p><strong>결재 라인 간소화</strong></p></th><th><p>기안자&gt;부서장(검토)</p><p>&gt;복무담당(협조)&gt;인사팀장(협조)</p><p>&gt;실/본부장(검토)</p><p>&gt;대표이사(결재)</p></th></tr><tr><th colspan="2"><p><strong>분할사용에 따른 신청양식 개선</strong></p></th><th><p>(신 규)</p></th></tr></thead><tbody></tbody></table><table><colgroup><col style="width:45%;"><col style="width:54%;"></colgroup><thead><tr><th><p><strong>구 분</strong></p></th><th style="text-align:center;"><p><strong>기 한</strong></p></th></tr></thead><tbody><tr><td><p>부서장 협의</p></td><td style="text-align:center;"><p>휴가 시작일로부터</p><p>1개월 전</p></td></tr></tbody></table><table><colgroup><col style="width:45%;"><col style="width:54%;"></colgroup><thead><tr><th><p><strong>구 분</strong></p></th><th style="text-align:center;"><p><strong>기 한</strong></p></th></tr></thead><tbody><tr><td><p>부서장 협의</p></td><td style="text-align:center;"><p>휴가</p><p>시작일로부터 일주일 전</p></td></tr></tbody></table><table tabindex="0"><thead><tr><th></th><th></th></tr></thead></table><table tabindex="0"><thead><tr><th></th><th></th></tr></thead></table><table tabindex="0"><thead><tr><th></th><th></th></tr></thead></table><table tabindex="0"><thead><tr><th></th><th></th></tr></thead></table><h1 id="시행원칙-및-절차" tabindex="-1">시행원칙 및 절차 <a class="header-anchor" href="#시행원칙-및-절차" aria-label="Permalink to &quot;시행원칙 및 절차&quot;">​</a></h1><h2 id="시행원칙" tabindex="-1">시행원칙 <a class="header-anchor" href="#시행원칙" aria-label="Permalink to &quot;시행원칙&quot;">​</a></h2><p>Ⅲ</p><p><strong>ㅇ 업무공백 방지를 위해 부서장과 사전 협의</strong></p><p><strong>ㅇ 휴가는 한 번에 사용하는 것이 원칙이나 기준에 따라 분할사용 가능 ㅇ 축제, 행정사무감사, 경영평가 등 부서 주요업무 추진기간 중 휴가 자제 ㅇ 휴가로 인한 업무공백이 발생하지 않도록 대직자 지정과 업무 인수인계 철저</strong></p><h2 id="시행절차" tabindex="-1">시행절차 <a class="header-anchor" href="#시행절차" aria-label="Permalink to &quot;시행절차&quot;">​</a></h2><table><colgroup><col style="width:17%;"><col style="width:23%;"><col style="width:58%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>구 분</strong></p></th><th style="text-align:center;"><p><strong>기 한</strong></p></th><th style="text-align:center;"><p><strong>내 용</strong></p></th></tr></thead><tbody><tr><td><p>부서장 협의</p></td><td><p>휴가 시작일로부터 일주일 전</p></td><td><ul><li><p>재충전휴가 계획을 부서장과 협의</p></li><li><p>업무에 지장이 없는 범위 내에서 휴가기간 선정</p></li></ul></td></tr></tbody></table><p>▼</p><table><colgroup><col style="width:26%;"><col style="width:73%;"></colgroup><thead><tr><th><p>팀장, 매니저 및 팀원</p></th><th><p>기안자&gt;부서장(검토)&gt;복무담당(협조)</p><p>&gt;실장(검토)&gt;본부장(전결)</p><p>※ 본부장 없는 부서는 실장(전결)</p></th></tr></thead><tbody><tr><td><p>실장</p></td><td><p>기안자&gt;본부장(검토)&gt;복무담당(협조)</p><p>&gt;대표이사(결재)</p></td></tr><tr><td><p>본부장 및 전문위원</p></td><td><p>기안자&gt;복무담당(협조)&gt;대표이사(결재)</p></td></tr></tbody></table><table><colgroup><col style="width:17%;"><col style="width:23%;"><col style="width:58%;"></colgroup><thead><tr><th><p>‘장기재직자 재충전휴가 계획’ 기안</p></th><th><p>휴가 시작일로부터 3일 전</p></th><th><ul><li><p>휴가계획서(붙임 2)를 작성하여 기안</p></li><li><p>결재라인</p></li></ul></th></tr></thead><tbody></tbody></table><p>▼</p><table><colgroup><col style="width:17%;"><col style="width:23%;"><col style="width:58%;"></colgroup><thead><tr><th><p>근무상황부 상신</p></th><th><p>시행 시점 전</p></th><th><p>- 더존iU&gt;근무상황부&gt;장기재직자재충전휴가 상신</p><p>※ 결재라인: 부서장(전결)</p></th></tr></thead><tbody></tbody></table><h2 id="재직기간별-휴가일수-및-신청방법" tabindex="-1">재직기간별 휴가일수 및 신청방법 <a class="header-anchor" href="#재직기간별-휴가일수-및-신청방법" aria-label="Permalink to &quot;재직기간별 휴가일수 및 신청방법&quot;">​</a></h2><p><strong>ㅇ 휴가일수 및 분할사용 방법</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>구 분</strong></th><th style="text-align:center;"><strong>휴가일수</strong></th><th style="text-align:center;"><strong>최대 사용횟수</strong></th><th><strong>비 고</strong></th></tr></thead><tbody><tr><td style="text-align:center;">30년 이상</td><td style="text-align:center;">25</td><td style="text-align:center;">5</td><td></td></tr><tr><td style="text-align:center;">20년 이상 30년 미만</td><td style="text-align:center;">25</td><td style="text-align:center;">5</td><td></td></tr><tr><td style="text-align:center;">10년 이상 20년 미만</td><td style="text-align:center;">15</td><td style="text-align:center;">3</td><td></td></tr><tr><td style="text-align:center;">5년 이상 10년 미만</td><td style="text-align:center;">5</td><td style="text-align:center;">1</td><td>분할사용 불가</td></tr></tbody></table><p>- 휴가는 한 번에 사용하는 것이 원칙이나 상기 기준에 따라 분할사용 가능</p><p>- <strong>1회당 최소 5일 이상</strong> 사용해야 하나 잔여일수가 5일 미만의 경우 잔여일수만큼</p><p>사용 가능</p><p>【예시1】15일 : 15일 모두 사용 또는 5+7+3, 6+6+3 등의 방법으로 실시</p><p>【예시2】25일 : 10+15일, 5+5+15, 5+5+5+5+5일 등의 방법으로 실시</p><ul><li>장기재직자 재충전휴가는 오랜 기간 사용이(5~10년) 가능하므로, 구분연수 내 사용해야 하며 이월 불가</li></ul><p><strong>ㅇ 연도 중 기간 도래자의 경우</strong></p><ul><li>연도 중 기간 도래자의 경우, 해당연도 말일까지 사용 가능</li></ul><p>【예시】입사일자가 2004.3.15인 직원의 경우</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>구분</strong></th><th style="text-align:center;"><strong>휴가일수</strong></th><th style="text-align:center;"><strong>사용기한</strong></th></tr></thead><tbody><tr><td style="text-align:center;">10년 이상 19년 미만</td><td style="text-align:center;">15</td><td style="text-align:center;">2024.12.31까지 사용 가능</td></tr><tr><td style="text-align:center;">20년 이상 30년 미만</td><td style="text-align:center;">25</td><td style="text-align:center;">2024.3.15부터 사용 가능</td></tr></tbody></table><p><strong>→</strong> 입사일자가 2004.3.15인 직원의 경우, 2024.3.15자로 재직기간이 20년이 도래하여도 2024.12.31까지는 19년차 장기재직자 재충전휴가 사용 가능</p><h1 id="휴가-시-유의사항" tabindex="-1">휴가 시 유의사항 <a class="header-anchor" href="#휴가-시-유의사항" aria-label="Permalink to &quot;휴가 시 유의사항&quot;">​</a></h1><ul><li>상위 직급자가 재충전휴가를 적극 사용하여 직원들이 휴가를 사용할 수 있는 자연스러운 분위기 조성</li></ul><p>Ⅴ</p><ul><li><p>휴가 중 긴급 연락이 가능하도록 비상연락체계 반드시 유지</p></li><li><p>휴가자 담당업무를 대직자에게 인계하여 업무 연속성 유지</p></li><li><p>대내/외 협조기관 및 부서와 사전 소통</p></li><li><p>연1회 실태조사를 통하여, 휴가일수 초과사용 시 연차 공제 예정</p></li><li><p>재충전 효과의 극대화를 위해 연차와 연계사용 가능</p></li></ul><p><strong>ㅇ 장기재직자 재충전휴가와 별도로 연차 상신 필요</strong></p><p><strong>관련문서 1. 대표이사 방침 제 309(인사팀-2975, 2023.10.19.)호</strong></p><p><strong>“서울문화재단 장기재직자 재충전휴가 사용지침 개정” 1부.</strong></p><p><strong>붙임문서 1. 서울문화재단 복무규정 1부.</strong></p><ol start="2"><li><p><strong>2024년 서울특별시 공무원 휴가 등 업무지침(2024.2.7.).</strong></p></li><li><p><strong>휴가계획서 양식 1부. 끝.</strong></p></li></ol>',64)]))}const C=e(g,[["render",h]]);export{E as __pageData,C as default};
